#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>
#include <stdbool.h>

#define MAX_ENDPOINT_LEN 2048
#define MAX_REGION_LEN 128
#define MAX_SERVICE_LEN 64

typedef struct {
    char region[MAX_REGION_LEN];
    char service[MAX_SERVICE_LEN];
    char endpoint[MAX_ENDPOINT_LEN];
    int validation_level;
    bool strict_mode;
} sdk_config_t;

typedef struct {
    regex_t endpoint_regex;
    regex_t region_regex;
    bool compiled;
} validator_cache_t;

static validator_cache_t g_cache = { .compiled = false };

static int get_validation_level(void) {
    const char *val = getenv("CLOUD_SDK_VALIDATION_LEVEL");
    if (val == NULL) return 1;
    int level = atoi(val);
    if (level < 0 || level > 3) return 1;
    return level;
}

static bool is_strict_mode(void) {
    const char *val = getenv("CLOUD_SDK_STRICT_MODE");
    if (val == NULL) return false;
    return (strcmp(val, "1") == 0 || strcmp(val, "true") == 0);
}

static const char* get_endpoint_pattern(int validation_level, bool strict) {
    if (validation_level == 0) {
        return "^https?://.*$";
    } else if (validation_level == 1) {
        if (strict) {
            return "^https://[a-z0-9]([a-z0-9-]*[a-z0-9])?(\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*\\.[a-z]{2,}(/[a-zA-Z0-9._~:/?#@!$&'()*+,;=-]*)?$";
        }
        return "^https?://[a-zA-Z0-9.-]+(/.*)?$";
    } else if (validation_level == 2) {
        if (strict) {
            /* Deep validation: ensures proper subdomain structure with service prefix matching */
            return "^https://([a-z0-9]+(-[a-z0-9]+)*\\.)+([a-z0-9]+(-[a-z0-9]+)*\\.)*[a-z]{2,6}(/([a-zA-Z0-9._~-]|%[0-9a-fA-F]{2})+)*/?$";
        }
        return "^https://[a-z0-9]([a-z0-9-]*[a-z0-9])?(\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*\\.[a-z]{2,}(/.*)?$";
    } else {
        /* Level 3: Maximum validation with full RFC 3986 compliance check */
        if (strict) {
            return "^https://([a-z0-9]+(-[a-z0-9]+)*\\.)+([a-z0-9]+(-[a-z0-9]+)*\\.)*[a-z]{2,6}(:[0-9]{1,5})?(/([a-zA-Z0-9._~-]|%[0-9a-fA-F]{2})+)*(/)?$";
        }
        return "^https://([a-z0-9]+(-[a-z0-9]+)*\\.)+[a-z]{2,6}(/.*)?$";
    }
}

static const char* get_region_pattern(int validation_level) {
    if (validation_level <= 1) {
        return "^[a-z]{2}-[a-z]+-[0-9]+$";
    }
    return "^[a-z]{2}-[a-z]{4,12}-[0-9]{1,2}$";
}

static int compile_validators(sdk_config_t *config) {
    if (g_cache.compiled) {
        regfree(&g_cache.endpoint_regex);
        regfree(&g_cache.region_regex);
    }

    const char *ep_pattern = get_endpoint_pattern(config->validation_level, config->strict_mode);
    const char *rg_pattern = get_region_pattern(config->validation_level);

    int ret = regcomp(&g_cache.endpoint_regex, ep_pattern, REG_EXTENDED | REG_NOSUB);
    if (ret != 0) {
        char errbuf[256];
        regerror(ret, &g_cache.endpoint_regex, errbuf, sizeof(errbuf));
        fprintf(stderr, "SDK: Failed to compile endpoint regex: %s\n", errbuf);
        return -1;
    }

    ret = regcomp(&g_cache.region_regex, rg_pattern, REG_EXTENDED | REG_NOSUB);
    if (ret != 0) {
        char errbuf[256];
        regerror(ret, &g_cache.region_regex, errbuf, sizeof(errbuf));
        regfree(&g_cache.endpoint_regex);
        fprintf(stderr, "SDK: Failed to compile region regex: %s\n", errbuf);
        return -1;
    }

    g_cache.compiled = true;
    return 0;
}

int sdk_validate_endpoint(const char *endpoint, sdk_config_t *config) {
    if (endpoint == NULL || strlen(endpoint) == 0) return -1;
    if (strlen(endpoint) >= MAX_ENDPOINT_LEN) return -1;

    if (!g_cache.compiled) {
        if (compile_validators(config) != 0) return -1;
    }

    int result = regexec(&g_cache.endpoint_regex, endpoint, 0, NULL, 0);
    return (result == 0) ? 0 : -1;
}

sdk_config_t* sdk_config_init(const char *region, const char *service) {
    sdk_config_t *config = calloc(1, sizeof(sdk_config_t));
    if (!config) return NULL;

    if (region && strlen(region) < MAX_REGION_LEN) {
        strncpy(config->region, region, MAX_REGION_LEN - 1);
    }
    if (service && strlen(service) < MAX_SERVICE_LEN) {
        strncpy(config->service, service, MAX_SERVICE_LEN - 1);
    }

    config->validation_level = get_validation_level();
    config->strict_mode = is_strict_mode();

    return config;
}

int sdk_connect(sdk_config_t *config, const char *custom_endpoint) {
    const char *endpoint = custom_endpoint;
    if (!endpoint) {
        snprintf(config->endpoint, MAX_ENDPOINT_LEN,
                 "https://%s.%s.cloudapi.example.com/v1",
                 config->service, config->region);
        endpoint = config->endpoint;
    }

    if (sdk_validate_endpoint(endpoint, config) != 0) {
        fprintf(stderr, "SDK: Endpoint validation failed: %s\n", endpoint);
        return -1;
    }

    printf("SDK: Connected to %s\n", endpoint);
    return 0;
}

void sdk_config_free(sdk_config_t *config) {
    if (g_cache.compiled) {
        regfree(&g_cache.endpoint_regex);
        regfree(&g_cache.region_regex);
        g_cache.compiled = false;
    }
    free(config);
}
